{
  "findings": [
    {
      "ref": "[D526]",
      "area": "contact",
      "claim": "A parent reports that Roblox allows voice chat with strangers and it can be turned off.",
      "stance": "risk",
      "quote": "Roblox's chat features make it easy for kids to connect with friends, but they also allow interactions with strangers. While Roblox uses filters to block inappropriate language in text and voice conversations, some users find ways around these filters, and this moderation may even encourage kids to continue conversations on other platforms where monitoring is limited."
    },
    {
      "ref": "[D526]",
      "area": "money",
      "claim": "A parent reports that Roblox pushes in-app purchases of Robux and uses social pressure to encourage spending.",
      "stance": "risk",
      "quote": "Roblox uses a virtual currency called \"Robux,\" which costs real money. Many platforms like this use \"freemium\" features, where spending money enhances the experience, so it's important to set boundaries early on."
    },
    {
      "ref": "[D526]",
      "area": "data",
      "claim": "A parent reports that Roblox collects user data and may share it with third parties for advertising.",
      "stance": "risk",
      "quote": "Roblox uses filters to block inappropriate language in text and voice conversations, but some users find ways around these filters, and this moderation may even encourage kids to continue conversations on other platforms where monitoring is limited."
    },
    {
      "ref": "[D526]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox's age gating is not fully effective, as inappropriate content can still slip through filters.",
      "stance": "risk",
      "quote": "Roblox doesn't have a strict age minimum, but it does use different ratings for game content... While these Roblox experience ratings aim to guide users toward age-appropriate games, it's possible for inappropriate content to slip through."
    },
    {
      "ref": "[D526]",
      "area": "content",
      "claim": "A parent reports that kids may encounter inappropriate content such as sexual themes, violence, and bullying in Roblox games.",
      "stance": "risk",
      "quote": "Because Roblox is user-generated, kids may still run into inappropriate content despite the platform's safety filters. This includes \"condo games\" (which usually feature adult themes and sexual content), violent games, gambling-style play, and even games that may have bullying or hate speech."
    },
    {
      "ref": "[D526]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced safety concerns and regulatory scrutiny over its handling of child safety.",
      "stance": "risk",
      "quote": "Following safety concerns, Roblox is rolling out new protections for under-13 users in November and December 2024. These updates include mandatory age ratings for games, limits on social spaces, and restrictions on unmoderated content. Since these changes are new and won't be fully enforced until 2025, we're not sure what their impact will be."
    }
  ]
}
